public String minimumBribes(int[] q) {
    int n = q.length;
    long bribes = 0;
    for (int i = 0; i < n; i++) {
        if (q[i] - (i + 1) > 2) {
            return "Too chaotic";
        }
        int start = Math.max(0, q[i] - 2);
        for (int j = start; j < i; j++) {
            if (q[j] > q[i]) {
                bribes++;
            }
        }
    }
    return Long.toString(bribes);
}

